function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'RangeFreqQuery' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with RangeFreqQuery(arr).';
  const arr = args[0][0];
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 100000) return 'arr needs 1 to 100000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each arr value is an integer from 1 to 10000.';
  if (operations.length - 1 > 100000) return 'At most 100000 queries.';
  for (let k = 1; k < operations.length; k++) {
    if (operations[k] !== 'query' || !Array.isArray(args[k]) || args[k].length !== 3) return 'After the constructor, every call is query(left, right, value).';
    const [left, right, value] = args[k];
    if (![left, right, value].every(Number.isInteger)) return 'query takes three integers.';
    if (left < 0 || left > right || right >= arr.length) return 'query needs 0 <= left <= right < arr.length.';
    if (value < 1 || value > 10000) return 'value is an integer from 1 to 10000.';
  }
  return null;
}

