class RangeFreqQuery {
  constructor(arr) {
    this.positions = new Map();
    for (let i = 0; i < arr.length; i++) {
      if (!this.positions.has(arr[i])) {
        this.positions.set(arr[i], []);
      }
      this.positions.get(arr[i]).push(i);
    }
  }

  query(left, right, value) {
    const indices = this.positions.get(value);
    if (!indices) {
      return 0;
    }
    return this.lowerBound(indices, right + 1) - this.lowerBound(indices, left);
  }

  lowerBound(indices, target) {
    let low = 0;
    let high = indices.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (indices[mid] < target) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    return low;
  }
}

