function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(1, 10);
  const top = size === 'large' ? [3, 40, 10000][int(0, 2)] : rand() < 0.8 ? 4 : 10000;
  const arr = Array.from({ length: n }, () => int(1, top));
  const calls = size === 'large' ? 499 : int(1, 12);
  const operations = ['RangeFreqQuery'];
  const args = [[arr]];
  for (let q = 0; q < calls; q++) {
    const left = int(0, n - 1);
    const right = rand() < 0.2 ? n - 1 : int(left, n - 1);
    const value = rand() < 0.8 ? arr[int(0, n - 1)] : int(1, top);
    operations.push('query');
    args.push([left, right, value]);
  }
  return [operations, args];
}
